namespace Loupedeck.ConverterPlugin
{
    using System;

    // Dial action for the MX Creative Dialpad: rotate to choose an output format, press to
    // convert. The current format is shown next to the dial; pressing the dial (the reset
    // command generated by `hasReset: true`) converts the most recent source file to it.
    public class FormatDialAdjustment : PluginDynamicAdjustment
    {
        private Int32 _index = 0;

        public FormatDialAdjustment()
            : base(
                displayName: "Convert: Pick Format & Press",
                description: "Rotate to choose an output format, press to convert the latest file.",
                groupName: "Convert",
                hasReset: true)
        {
        }

        // Rotating the dial moves through the list of formats, wrapping around at both ends.
        protected override void ApplyAdjustment(String actionParameter, Int32 diff)
        {
            var count = ConversionFormat.All.Count;
            this._index = ((this._index + diff) % count + count) % count;
            this.AdjustmentValueChanged();
        }

        // Pressing the dial runs the conversion to the currently selected format.
        protected override void RunCommand(String actionParameter)
        {
            var format = ConversionFormat.All[this._index];
            ConvertRunner.Run(this.Plugin, format);
            this.AdjustmentValueChanged();
        }

        protected override String GetAdjustmentValue(String actionParameter) =>
            ConversionFormat.All[this._index].DisplayName;
    }
}
